<script setup>
import {ref,onMounted} from 'vue'
import {voiceApi,stamp} from '../voice/operations'
const state=ref(null),status=ref('awaiting_review'),search=ref(''),page=ref(1),selected=ref(null),form=ref(null),error=ref(''),notice=ref(''),busy=ref(false)
const labels={awaiting_review:'Aguardando revisão',qualified:'Qualificado',discarded:'Descartado'}
async function load(){state.value=await voiceApi('/leads?'+new URLSearchParams({status:status.value,search:search.value,page:page.value}))}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
function open(l){if(form.value){error.value='Salve ou cancele a revisão atual antes de abrir outro lead.';return}selected.value=l;form.value={revision:l.revision,status:l.status,assigned_user_id:l.assigned_user_id||null,review_notes:l.review_notes||''}}
async function save(){await voiceApi('/leads/'+selected.value.id,'PUT',form.value);selected.value=null;form.value=null;notice.value='Revisão salva. Nenhuma mensagem ou chamada foi iniciada.';await load()}
defineExpose({requestLeave:fn=>{if(form.value){error.value='Salve ou cancele a revisão antes de sair.';return}fn()}})
onMounted(()=>run(load))
</script>
<template><section class="leads table-card"><div class="heading"><div><span class="eyebrow">DA ORIGEM AO RESPONSÁVEL</span><h2>Leads de integrações</h2><p>Revise os dados recebidos de formulários e escolha quem dará continuidade.</p></div><button class="secondary" :disabled="busy" @click="run(load)">Atualizar leads</button></div><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><div class="counts"><span v-for="(label,key) in labels">{{label}} <strong>{{state?.counts[key]||0}}</strong></span></div><form class="filters" @submit.prevent="page=1;run(load)"><label>Estado<select v-model="status"><option value="">Todos</option><option v-for="(label,key) in labels" :value="key">{{label}}</option></select></label><label>Buscar lead<input v-model="search" placeholder="Nome, telefone ou referência"></label><button class="secondary" :disabled="busy">Filtrar leads</button></form><div class="scroll"><table><thead><tr><th>Contato</th><th>Origem</th><th>Estado</th><th>Responsável</th><th>Recebido em</th><th></th></tr></thead><tbody><tr v-for="l in state?.rows.data" :key="l.id"><td><strong>{{l.name||'A identificar'}}</strong><br>{{l.phone||l.email||'Sem contato'}}</td><td>{{l.source}}<small>{{l.external_id}}</small></td><td>{{labels[l.status]||l.status}}<small v-if="l.suppressed_at">Contato solicitou interrupção</small></td><td>{{state.agents.find(a=>a.id===l.assigned_user_id)?.name||'Sem responsável'}}</td><td>{{stamp(l.created_at)}}</td><td><button class="secondary" @click="open(l)">Revisar lead</button></td></tr></tbody></table></div><p v-if="!state?.rows.data.length">Nenhum lead neste filtro. Entradas enviadas pela API aparecerão aqui.</p><div class="filters"><button class="secondary" :disabled="busy||page===1" @click="page--;run(load)">Anterior</button><span>{{page}} / {{state?.rows.last_page||1}}</span><button class="secondary" :disabled="busy||page>=(state?.rows.last_page||1)" @click="page++;run(load)">Próxima</button></div><form v-if="form" class="review" @submit.prevent="run(save)"><h3>Revisar: {{selected.name||selected.phone||selected.external_id}}</h3><p>{{selected.email}} · {{selected.phone}}</p><p :class="{'error':selected.suppressed_at}">{{selected.suppressed_at?'Contato pediu interrupção. A revisão preserva esse bloqueio.':selected.contact_consent?'O contato vinculado tem autorização registrada.':'Contato sem autorização registrada para campanhas.'}}</p><details><summary>Autorização informada na entrada e origem</summary><p>{{selected.consent?'Entrada informa autorização':'Entrada não informa autorização'}} · {{selected.consent_evidence||'Sem evidência informada'}}</p><pre>{{selected.attribution?JSON.parse(selected.attribution):{} }}</pre></details><div class="filters"><label>Estado<select v-model="form.status"><option v-for="(label,key) in labels" :value="key">{{label}}</option></select></label><label>Responsável<select v-model="form.assigned_user_id"><option :value="null">Sem responsável</option><option v-for="a in state.agents" :value="a.id">{{a.name}}</option></select></label></div><label>Observações<textarea v-model="form.review_notes" maxlength="2000" :required="form.status==='discarded'" placeholder="Próximo passo ou motivo do descarte"/></label><div class="filters"><button class="primary" :disabled="busy">Salvar revisão</button><button type="button" class="secondary" :disabled="busy" @click="selected=null;form=null">Cancelar revisão</button></div></form><p class="hint">Qualificar ou atribuir um lead não concede autorização, não adiciona a cadências e não envia WhatsApp. O histórico de consentimento é preservado.</p></section></template>
<style scoped>.leads{padding:24px;margin-top:24px}.heading,.filters,.counts{display:flex;align-items:end;gap:16px;flex-wrap:wrap}.heading{justify-content:space-between}.leads h2{font-size:22px}.leads p,.hint{color:#747e6b;line-height:1.7}.counts{margin:22px 0}.counts span{background:#f5f2e8;padding:12px 16px;border-radius:12px;font-size:12px}.counts strong{margin-left:12px}.filters{margin:18px 0}.leads label{display:flex;flex-direction:column;gap:8px;font-size:12px}.leads select{border:1px solid #daddd2;border-radius:9px;padding:12px;background:white}.scroll{overflow:auto}.leads table{font-size:12px}.leads small{display:block;margin-top:5px;color:#787e71}.review{padding:22px;background:#f8f7f1;border:1px solid #dfdfd3;border-radius:16px;margin-top:24px}.review textarea{min-height:100px}.review pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.hint{font-size:12px}@media(max-width:600px){.leads{padding:16px}.filters label{width:100%}}</style>
